"""Behavioral tests for the optional, offline snapshot example (stdlib only)."""
import base64
import copy
import hashlib
import json
import os
import re
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from html.parser import HTMLParser


RENDERER = Path(__file__).with_name("render.py")
# A complete 1x1 PNG fixture, not an image generated by the renderer.
PNG = base64.b64decode(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aZ1sAAAAASUVORK5CYII="
)


class Tags(HTMLParser):
    def __init__(self, text):
        super().__init__()
        self.tags = []
        self.regions = []
        self.viewboxes = []
        self.feed(text)

    def handle_starttag(self, tag, attrs):
        self.tags.append(tag)
        attrs = dict(attrs)
        if tag == "rect" and "data-finding" in attrs:
            self.regions.append(attrs["data-finding"])
        if tag == "svg" and "viewbox" in attrs:
            self.viewboxes.append([float(v) for v in re.split(r"[\s,]+", attrs["viewbox"])])


class RendererTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)
        (self.root / "capture.png").write_bytes(PNG)
        (self.root / "source.html").write_text("<main>Fixture, not a measured user outcome.</main>")
        source_hash = self.digest("source.html")
        report = {
            "browser": "fixture-browser",
            "sourceSha256": source_hash,
            "captures": [{"width": 1, "state": "empty", "file": "capture.png",
                          "viewport": 1, "document": 1, "scrollY": 12,
                          "framing": "natural viewport", "active": {"tag": "INPUT", "name": ""}}],
            "checks": [{"width": 1, "name": "fixture check", "pass": True}],
        }
        (self.root / "report.json").write_text(json.dumps(report))
        finding = {
            "id": "visible", "captureId": "fixture", "kind": "rendered-observation",
            "title": "Visible context", "observation": "A retained fixture region.",
            "consequence": "Supports inspection of this region only.",
            "applicability": "This synthetic test fixture.", "decision": "keep",
            "recheck": "Inspect a changed capture.", "limits": "No behavior was executed.",
            "sourceHint": None, "rect": [0, 0, 1, 1],
        }
        source_only = dict(finding, id="markup", kind="source-fact", title="Source only",
                           observation="Source content does not establish visibility.", rect=None,
                           decision="unassessed", sourceHint="#not-measured")
        self.document = {
            "format": "tasteforge.rendered-evidence.prototype.v1",
            "sourceRevision": "a" * 40,
            "captures": [{"id": "fixture", "state": "empty", "viewportWidth": 1,
                          "image": self.asset("capture.png"), "source": self.asset("source.html"),
                          "report": self.asset("report.json")}],
            "findings": [finding, source_only],
        }

    def digest(self, name):
        return hashlib.sha256((self.root / name).read_bytes()).hexdigest()

    def asset(self, name):
        return {"path": name, "sha256": self.digest(name)}

    def run_renderer(self, document=None, output="out/view.html"):
        (self.root / "annotations.json").write_text(json.dumps(document or self.document))
        return subprocess.run(
            [sys.executable, str(RENDERER), "--root", str(self.root),
             "--annotations", "annotations.json", "--out", str(self.root / output)],
            capture_output=True, text=True, timeout=20,
        )

    def rejected(self, document=None, trace="", output="out/view.html"):
        result = self.run_renderer(document, output)
        self.assertEqual(result.returncode, 2, result.stdout + result.stderr)
        self.assertIn(trace, result.stderr)
        self.assertFalse((self.root / output).exists(), "Invalid evidence created an output")
        return result

    def test_valid_snapshot_is_self_contained_and_source_only_has_no_region(self):
        result = self.run_renderer()
        self.assertEqual(result.returncode, 0, result.stderr)
        text = (self.root / "out/view.html").read_text()
        tags = Tags(text)
        self.assertIn("data:image/png;base64," + base64.b64encode(PNG).decode(), text)
        self.assertEqual(tags.regions, ["visible"])
        self.assertIn("Source only", text)
        self.assertIn("checkbox", text)
        self.assertNotIn("script", tags.tags)
        self.assertIn("12", text)  # The recorded natural scroll, not an assumed zero.
        self.assertNotIn(str(self.root), text)

    def test_same_inputs_produce_identical_output_in_different_new_files(self):
        self.assertEqual(self.run_renderer(output="one.html").returncode, 0)
        self.assertEqual(self.run_renderer(output="two.html").returncode, 0)
        self.assertEqual((self.root / "one.html").read_bytes(), (self.root / "two.html").read_bytes())

    def test_authored_text_is_escaped_instead_of_executed_as_markup(self):
        self.document["findings"][0]["observation"] = "<script>throw new Error('unsafe')</script>"
        self.document["findings"][0]["sourceHint"] = '<img src="x" onerror="unsafe()">'
        result = self.run_renderer()
        self.assertEqual(result.returncode, 0, result.stderr)
        text = (self.root / "out/view.html").read_text()
        self.assertNotIn("script", Tags(text).tags)
        self.assertIn("&lt;script&gt;", text)
        self.assertIn("&lt;img", text)

    def test_capture_pixels_are_not_reinterpreted_as_css_viewport_pixels(self):
        report = json.loads((self.root / "report.json").read_text())
        report["captures"][0].update(width=2, viewport=2, document=2)
        (self.root / "report.json").write_text(json.dumps(report))
        self.document["captures"][0].update(viewportWidth=2, report=self.asset("report.json"))
        result = self.run_renderer()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn([0, 0, 1, 1], Tags((self.root / "out/view.html").read_text()).viewboxes)

    def test_stale_image_source_and_report_each_block_output(self):
        for name in ["capture.png", "source.html", "report.json"]:
            with self.subTest(asset=name):
                path = self.root / name
                before = path.read_bytes()
                path.write_bytes(before + b" ")
                self.rejected(trace=name)
                path.write_bytes(before)

    def test_correct_hashes_do_not_authorize_a_wrong_source_report_join(self):
        report = json.loads((self.root / "report.json").read_text())
        report["sourceSha256"] = "b" * 64
        (self.root / "report.json").write_text(json.dumps(report))
        self.document["captures"][0]["report"] = self.asset("report.json")
        self.rejected(trace="source")

    def test_capture_state_and_filename_must_match_one_report_entry(self):
        document = copy.deepcopy(self.document)
        document["captures"][0]["state"] = "success"
        self.rejected(document, trace="fixture")

    def test_bool_fractional_negative_and_outside_rectangles_are_rejected(self):
        for rect in [[True, 0, 1, 1], [0.5, 0, 1, 1], [-1, 0, 1, 1], [0, 0, 0, 1], [0, 0, 2, 1]]:
            with self.subTest(rect=rect):
                document = copy.deepcopy(self.document)
                document["findings"][0]["rect"] = rect
                self.rejected(document, trace="visible")

    def test_duplicate_and_unresolved_ids_are_rejected(self):
        document = copy.deepcopy(self.document)
        document["findings"][1]["id"] = "visible"
        self.rejected(document, trace="visible")
        document = copy.deepcopy(self.document)
        document["findings"][0]["captureId"] = "missing"
        self.rejected(document, trace="missing")

    def test_non_string_capture_references_are_rejected_without_a_traceback(self):
        for value in [[], {}, True, None]:
            with self.subTest(value=value):
                document = copy.deepcopy(self.document)
                document["findings"][0]["captureId"] = value
                result = self.rejected(document, trace="captureId")
                self.assertNotIn("Traceback", result.stderr)

    def test_boolean_runtime_viewport_is_not_treated_as_an_integer(self):
        report = json.loads((self.root / "report.json").read_text())
        report["captures"][0]["viewport"] = True
        (self.root / "report.json").write_text(json.dumps(report))
        self.document["captures"][0]["report"] = self.asset("report.json")
        self.rejected(trace="viewport")

    def test_absolute_traversal_and_linked_assets_are_not_read(self):
        for name in ["../outside.png", str(self.root / "capture.png"), "a\\capture.png"]:
            with self.subTest(path=name):
                document = copy.deepcopy(self.document)
                document["captures"][0]["image"]["path"] = name
                self.rejected(document, trace="path")
        for link_kind in ["symbolic", "hard"]:
            with self.subTest(link_kind=link_kind):
                alias = self.root / "alias.png"
                if link_kind == "symbolic":
                    alias.symlink_to(self.root / "capture.png")
                else:
                    os.link(self.root / "capture.png", alias)
                document = copy.deepcopy(self.document)
                document["captures"][0]["image"]["path"] = "alias.png"
                try:
                    self.rejected(document, trace="link")
                finally:
                    alias.unlink()

    def test_unknown_format_fields_and_overlong_text_are_rejected(self):
        for mutate, trace in [
            (lambda d: d.update(format="unsupported"), "format"),
            (lambda d: d.update(extra=True), "extra"),
            (lambda d: d["captures"][0].update(extra=True), "extra"),
            (lambda d: d["findings"][0].update(extra=True), "extra"),
            (lambda d: d["findings"][0].update(title="x" * 4097), "title"),
            (lambda d: d["findings"][0].update(sourceHint="x" * 4097), "sourceHint"),
            (lambda d: d["findings"][0].pop("rect"), "rect"),
        ]:
            with self.subTest(trace=trace):
                document = copy.deepcopy(self.document)
                mutate(document)
                self.rejected(document, trace=trace)

    def test_linked_input_parent_is_rejected_even_for_a_regular_leaf(self):
        (self.root / "actual-assets").mkdir()
        (self.root / "actual-assets/capture.png").write_bytes(PNG)
        (self.root / "linked-assets").symlink_to(self.root / "actual-assets", target_is_directory=True)
        document = copy.deepcopy(self.document)
        document["captures"][0]["image"]["path"] = "linked-assets/capture.png"
        self.rejected(document, trace="link")

    def test_dot_path_components_are_not_silently_normalized(self):
        document = copy.deepcopy(self.document)
        document["captures"][0]["image"]["path"] = "./capture.png"
        self.rejected(document, trace="path")

    def test_capture_and_finding_count_caps_are_enforced_before_asset_reads(self):
        for field, count in [("captures", 5), ("findings", 9)]:
            with self.subTest(field=field):
                document = copy.deepcopy(self.document)
                document[field] = [copy.deepcopy(document[field][0]) for _ in range(count)]
                self.rejected(document, trace=field)

    def test_hash_matching_non_png_is_not_presented_as_an_image(self):
        (self.root / "capture.png").write_bytes(b"not a PNG image")
        self.document["captures"][0]["image"] = self.asset("capture.png")
        self.rejected(trace="PNG")

    def test_manifest_and_asset_byte_limits_prevent_output(self):
        (self.root / "source.html").write_bytes(b"x" * (2 * 1024 * 1024 + 1))
        self.document["captures"][0]["source"] = self.asset("source.html")
        self.rejected(trace="source.html")
        self.document["padding"] = "x" * (256 * 1024)
        self.rejected(trace="annotations.json")

    def test_existing_output_is_preserved_and_linked_parents_are_refused(self):
        existing = self.root / "existing.html"
        existing.write_text("preserve me")
        result = self.run_renderer(output="existing.html")
        self.assertEqual(result.returncode, 2)
        self.assertIn("existing.html", result.stderr)
        self.assertEqual(existing.read_text(), "preserve me")
        (self.root / "actual").mkdir()
        (self.root / "alias-output").symlink_to(self.root / "actual", target_is_directory=True)
        result = self.run_renderer(output="alias-output/new.html")
        self.assertEqual(result.returncode, 2)
        self.assertIn("link", result.stderr)
        self.assertFalse((self.root / "actual/new.html").exists())

    def test_missing_nested_output_parent_does_not_hide_a_linked_ancestor(self):
        (self.root / "actual").mkdir()
        (self.root / "alias-output").symlink_to(self.root / "actual", target_is_directory=True)
        result = self.run_renderer(output="alias-output/missing/view.html")
        self.assertEqual(result.returncode, 2)
        self.assertIn("link", result.stderr)
        self.assertFalse((self.root / "actual/missing").exists())

    def test_dangling_output_link_is_preserved_without_creating_its_target(self):
        output = self.root / "dangling.html"
        target = self.root / "must-not-create.html"
        output.symlink_to(target)
        result = self.run_renderer(output="dangling.html")
        self.assertEqual(result.returncode, 2)
        self.assertIn("dangling.html", result.stderr)
        self.assertTrue(output.is_symlink())
        self.assertFalse(target.exists())


if __name__ == "__main__":
    unittest.main()
